<?php

/**
 * Which chapters use the "explore, decide, see the consequence" Branching Scenario format (Study Deck V3 slides of kind
 * hotspots / decision / outcome / flow: the reference is content_master 64198), instead of the single-slide story format.
 *
 * Two things follow the same lists:
 *   - GENERATION: a Branching Scenario generated by hand for a chapter these lists name is built in the new format, with no per-chapter setting.
 *   - PRESENTATION: a Branching Scenario already stored in the older story format for such a chapter is shown in the new format
 *     (Branching\Pro\ProScenarioConverter). The stored deck is never changed: the conversion is made on every read, and switched off by
 *     `convert_existing`.
 *
 * A chapter takes the new format only when every list matches it; `*` matches anything. Add a standard to widen the rollout (no code change).
 */
return [
    'enabled' => (bool) env('STUDY_DECK_PRO_BRANCHING', true),

    // Show stored story-format Branching Scenarios of these chapters in the new format (read-only conversion; nothing is written).
    'convert_existing' => (bool) env('STUDY_DECK_PRO_CONVERT_EXISTING', true),

    // Matched against standard.name, subject.subject_name and chapter_master.sort_order of the chapter.
    'standards' => ['8', '9'],
    'subjects' => ['*'],
    'chapter_numbers' => ['*'],

    // The most slides a Branching Scenario may have, built now or shown from a stored one (aim: 30 to 40; never more than this). A new lesson
    // groups its topics into at most as many parts as fit; a stored one that is longer is condensed to its central decision in each part.
    'max_slides' => (int) env('STUDY_DECK_PRO_MAX_SLIDES', 50),

    // Subjects that are test data, not academic subjects: never converted and never built in the new format.
    'exclude_subjects' => ['module testing by vivek', 'Testing by APi'],

    // The sample the format was copied from (documentation only: nothing reads this row at run time).
    'reference_content_id' => 64198,
];
